// Merges the LLM analysis with the deterministic counts, compares against the previous
// interval, decides the urgent alert, and renders the Slack copy.
const batch = $('Build Interval Batch').first().json;
const raw = $input.first().json;

// The Gemini node's exact output shape varies (object at root, .content, or a JSON string),
// so walk the response for the first object that carries a sentiment block.
function findAnalysis(o, depth) {
  if (!o || depth > 6) return null;
  if (typeof o === 'string') { try { return findAnalysis(JSON.parse(o), depth + 1); } catch (e) { return null; } }
  if (typeof o !== 'object') return null;
  if (o.sentiment && typeof o.sentiment === 'object') return o;
  if (Array.isArray(o)) { for (const v of o) { const f = findAnalysis(v, depth + 1); if (f) return f; } return null; }
  for (const k of Object.keys(o)) { const f = findAnalysis(o[k], depth + 1); if (f) return f; }
  return null;
}
const a = findAnalysis(raw, 0) || {};
const llm_parsed = !!(a && a.sentiment);

const vol = Number(batch.message_volume || 0);
const num = v => { const x = Number(v); return Number.isFinite(x) && x >= 0 ? Math.round(x) : 0; };

let pos = num(a.sentiment && a.sentiment.positive);
let neu = num(a.sentiment && a.sentiment.neutral);
let neg = num(a.sentiment && a.sentiment.negative);

// Force the sentiment split to reconcile with the real volume.
if (vol === 0) { pos = 0; neu = 0; neg = 0; }
else {
  const sum = pos + neu + neg;
  if (sum === 0) { neu = vol; }
  else if (sum !== vol) {
    const f = vol / sum;
    pos = Math.round(pos * f);
    neg = Math.round(neg * f);
    neu = Math.max(0, vol - pos - neg);
  }
}

const strArr = (v, cap) => Array.isArray(v) ? v.map(x => String(x).trim()).filter(Boolean).slice(0, cap) : [];
const topics = strArr(a.trending_topics, 5);
const issues = strArr(a.emerging_issues, 5);
const actions = strArr(a.recommended_actions, 4);
const sfl = a.safety_fraud_legal === true || a.safety_fraud_legal === 'true';
const sflDetail = String(a.safety_fraud_legal_detail || '').trim();

const prev = batch.prev || null;
const prevVol = prev ? Number(prev.message_volume || 0) : 0;
const prevNeg = prev && prev.sentiment ? Number(prev.sentiment.negative || 0) : 0;
const prevNegShare = prevVol > 0 ? prevNeg / prevVol : 0;
const prevComplaints = prev ? Number(prev.complaints || 0) : 0;
const prevIssues = prev ? strArr(prev.emerging_issues, 99).map(s => s.toLowerCase()) : [];

const negShare = vol > 0 ? neg / vol : 0;
const volDelta = vol - prevVol;
const negShareDelta = Math.round((negShare - prevNegShare) * 1000) / 1000;
const newIssues = issues.filter(i => prevIssues.indexOf(i.toLowerCase()) === -1);
const complaints = Number(batch.complaint_count || 0);

const reasons = [];
if (sfl) reasons.push('Safety / fraud / legal concern flagged' + (sflDetail ? ': ' + sflDetail : ''));
if (negShareDelta >= 0.15 && neg >= 3) reasons.push('Negative sentiment share up ' + Math.round(negShareDelta * 100) + 'pts (' + neg + '/' + vol + ')');
if (vol >= 5 && negShare >= 0.5) reasons.push('Negative sentiment is ' + Math.round(negShare * 100) + '% of interval volume');
if (newIssues.length >= 2) reasons.push(newIssues.length + ' new operational issues: ' + newIssues.join('; '));
if (complaints >= 3 && complaints >= prevComplaints * 2 && complaints > prevComplaints) reasons.push('Complaints jumped ' + prevComplaints + ' -> ' + complaints);
if (prevVol > 0 && vol >= prevVol * 3 && vol >= 10) reasons.push('Volume spike ' + prevVol + ' -> ' + vol);

const urgent = reasons.length > 0;

// Canonical payload — exactly the requested schema.
const payload = {
  event_name: batch.event_name,
  interval: batch.interval_label,
  message_volume: vol,
  sentiment: { positive: pos, neutral: neu, negative: neg },
  trending_topics: topics,
  emerging_issues: issues,
  high_intent_messages: Number(batch.purchase_intent_count || 0),
  recommended_actions: actions,
  urgent_alert: urgent,
};

const sign = n => (n > 0 ? '+' : '') + n;
const pct = v => (vol > 0 ? Math.round(v / vol * 100) + '%' : '0%');
const kv = o => Object.keys(o || {}).map(k => k + ' ' + o[k]).join(' · ') || '—';

// The messages themselves — aggregate counts alone don't tell you what to reply to.
const KIND_ICON = { complaint: '🔴', intent: '💰', other: '⚪' };
const msgs = Array.isArray(batch.actionable_messages) ? batch.actionable_messages : [];
const actionableTotal = Number(batch.actionable_total || msgs.length);
function msgLine(m) {
  const head = ' ' + (KIND_ICON[m.kind] || '⚪') + ' ' + (m.fan_name || 'unknown') + ' · ' + m.platform +
    (m.time_label ? ' · ' + m.time_label : '') + ' — "' + m.text + '"';
  return m.reply_url ? head + '  <' + m.reply_url + '|Reply →>' : head;
}
const replyBlock = [];
if (msgs.length) {
  replyBlock.push('');
  replyBlock.push('*Needs a reply (' + msgs.length + ' of ' + actionableTotal + '):*');
  for (const m of msgs) replyBlock.push(msgLine(m));
  if (actionableTotal > msgs.length) replyBlock.push('_+' + (actionableTotal - msgs.length) + ' more this interval_');
}

const lines = [
  '*' + batch.event_name + '* — rolling report · interval ' + batch.interval_index,
  '`' + batch.window_start + '` → `' + batch.window_end + '`',
  '',
  '*Volume:* ' + vol + ' relevant (' + sign(volDelta) + ' vs prev)' + (batch.offtopic_count ? ' · ' + batch.offtopic_count + ' off-topic filtered' : ''),
  '*Sentiment:* 🟢 ' + pos + ' (' + pct(pos) + ') · ⚪ ' + neu + ' · 🔴 ' + neg + ' (' + pct(neg) + ') · Δneg ' + sign(Math.round(negShareDelta * 100)) + 'pts',
  '*Purchase intent:* ' + payload.high_intent_messages + ' · *Complaints:* ' + complaints + ' (prev ' + prevComplaints + ')',
  ...replyBlock,
  '',
  '*Trending:* ' + (topics.length ? topics.join(', ') : '—'),
  '*Emerging issues:* ' + (issues.length ? issues.join('; ') : '—') + (newIssues.length ? '  _(new: ' + newIssues.join('; ') + ')_' : ''),
  '*Platforms:* ' + kv(batch.by_platform) + '  ·  *Types:* ' + kv(batch.by_type),
  '*Notable fans:* ' + ((batch.notable_creators || []).map(f => f.fan_name + ' (' + f.count + ')').join(', ') || '—'),
  '*Recommended:* ' + (actions.length ? '\n' + actions.map(x => '  • ' + x).join('\n') : '—'),
];
if (urgent) lines.splice(2, 0, '🚨 *URGENT ALERT RAISED*');
if (batch.api_truncated) lines.push('_⚠️ MCP reported ' + batch.api_total + ' records but returned only ' + batch.fetched_events + ' (single page) — volume is undercounted._');
const droppedWindow = Number(batch.dropped_before || 0) + Number(batch.dropped_after || 0);
if (droppedWindow) lines.push('_ℹ️ ' + droppedWindow + ' of ' + batch.fetched_events + ' returned records fell outside this interval and were filtered out._');
if (batch.undated) lines.push('_ℹ️ ' + batch.undated + ' record(s) had no usable timestamp and were kept._');
if (batch.sample_truncated) lines.push('_⚠️ Only the first 60 messages were sent for analysis._');
if (!llm_parsed && vol > 0) lines.push('_⚠️ Could not parse the model response — sentiment defaulted to neutral._');

const alertLines = urgent ? [
  '🚨 *URGENT — ' + batch.event_name + '*',
  'Interval ' + batch.interval_index + '  `' + batch.window_start + '` → `' + batch.window_end + '`',
  '',
  ...reasons.map(r => '• ' + r),
  '',
  'Volume ' + vol + ' · 🔴 ' + neg + ' (' + pct(neg) + ') · complaints ' + complaints,
  ...replyBlock,
  actions.length ? '*Recommended:* ' + actions.join('; ') : '',
] : [];

return [{ json: Object.assign({}, batch, payload, {
  complaints,
  urgent_reasons: reasons,
  new_issues: newIssues,
  volume_delta: volDelta,
  negative_share_delta: negShareDelta,
  llm_parsed,
  payload_json: JSON.stringify(payload),
  metrics_snapshot_json: JSON.stringify(Object.assign({}, payload, { complaints })),
  report_text: lines.join('\n'),
  alert_text: alertLines.join('\n'),
}) }];

// Aggregates every stored interval into the post-event report.
// Config comes from the LOOP, not from Window Gate: Window Gate emits one item per active event,
// so $('Window Gate').first() would pin every iteration to event #1.
const cfg = $('Loop Over Events').first().json;
const rows = $input.all().map(i => i.json)
  .filter(r => r && r.event_name && r.interval_index !== undefined && r.event_name === cfg.event_name);
rows.sort((a, b) => Number(a.interval_index) - Number(b.interval_index));

function jarr(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) { try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; } }
  return [];
}

let vol = 0, pos = 0, neu = 0, neg = 0, intent = 0, comp = 0, alerts = 0;
const topicC = {}, issueC = {};
let peak = null;

for (const r of rows) {
  const v = Number(r.message_volume || 0);
  vol += v; pos += Number(r.sentiment_positive || 0); neu += Number(r.sentiment_neutral || 0);
  neg += Number(r.sentiment_negative || 0);
  intent += Number(r.high_intent_messages || 0); comp += Number(r.complaints || 0);
  if (r.urgent_alert === true || r.urgent_alert === 'true') alerts++;
  for (const t of jarr(r.trending_topics)) topicC[t] = (topicC[t] || 0) + 1;
  for (const t of jarr(r.emerging_issues)) issueC[t] = (issueC[t] || 0) + 1;
  if (!peak || v > Number(peak.message_volume || 0)) peak = r;
}

const rank = o => Object.keys(o).map(k => [k, o[k]]).sort((a, b) => b[1] - a[1]).slice(0, 8);
const pct = v => (vol > 0 ? Math.round(v / vol * 100) + '%' : '0%');

const summary = {
  event_name: cfg.event_name,
  intervals: rows.length,
  window: cfg.start_time + ' -> ' + cfg.end_time,
  total_volume: vol,
  sentiment: { positive: pos, neutral: neu, negative: neg },
  total_high_intent: intent,
  total_complaints: comp,
  urgent_intervals: alerts,
  top_topics: rank(topicC),
  top_issues: rank(issueC),
  peak_interval: peak ? { interval: peak.interval, volume: Number(peak.message_volume || 0) } : null,
};

const lines = [
  '🏁 *' + cfg.event_name + '* — POST-EVENT REPORT',
  '`' + cfg.start_time + '` → `' + cfg.end_time + '`',
  '',
  '*Intervals captured:* ' + rows.length,
  '*Total relevant volume:* ' + vol,
  '*Sentiment:* 🟢 ' + pos + ' (' + pct(pos) + ') · ⚪ ' + neu + ' (' + pct(neu) + ') · 🔴 ' + neg + ' (' + pct(neg) + ')',
  '*Purchase-intent messages:* ' + intent,
  '*Complaints:* ' + comp,
  '*Intervals that raised an urgent alert:* ' + alerts,
  '',
  '*Top topics:* ' + (rank(topicC).map(t => t[0] + ' (' + t[1] + ')').join(', ') || '—'),
  '*Top issues:* ' + (rank(issueC).map(t => t[0] + ' (' + t[1] + ')').join(', ') || '—'),
  '*Peak interval:* ' + (peak ? peak.interval + ' (' + peak.message_volume + ' msgs)' : '—'),
  '',
  '_Monitoring stopped automatically. All ' + rows.length + ' interval rows retained in `event_monitor_intervals`._',
];
if (!rows.length) lines.push('_No intervals were recorded for this event._');

return [{ json: {
  event_name: cfg.event_name,
  summary_json: JSON.stringify(summary),
  report_text: lines.join('\n'),
} }];
